mapper.select:
SELECT * FROM articles


        AND source = #{query.source}


        AND category = #{query.category}


        AND publish_date >= #{query.startDate}


        AND publish_date <= #{query.endDate}


        AND (title LIKE CONCAT('%', #{query.keyword}, '%')
            OR content LIKE CONCAT('%', #{query.keyword}, '%')
            OR keywords LIKE CONCAT('%', #{query.keyword}, '%'))


ORDER BY publish_date DESC, id DESC

SELECT DATE_FORMAT(publish_date, '%Y-%m') as date, COUNT(*) as count FROM articles WHERE publish_date IS NOT NULL
AND publish_date >= #{startDate}
AND publish_date <= #{endDate}
GROUP BY DATE_FORMAT(publish_date, '%Y-%m') ORDER BY date DESC
